using ClosedXML.Excel;
using Indamin.Performance.Data;
namespace Indamin.Performance.Services;
public class ExcelService{
 public byte[] Employees(IEnumerable<Employee> rows){using var wb=new XLWorkbook();var ws=wb.Worksheets.Add("کارکنان");var h=new[]{"کد پرسنلی","کد ملی","نام و نام خانوادگی","رده پستی","واحد","ارزیاب؟","سرپرست"};for(int i=0;i<h.Length;i++)ws.Cell(1,i+1).Value=h[i];int r=2;foreach(var e in rows){ws.Cell(r,1).Value=e.PersonnelNo;ws.Cell(r,2).Value=e.NationalNo;ws.Cell(r,3).Value=e.FullName;ws.Cell(r,4).Value=e.Position?.Title;ws.Cell(r,5).Value=e.Unit?.Title;ws.Cell(r,6).Value=e.IsEvaluator?"بله":"خیر";ws.Cell(r,7).Value=e.SupervisorId?.ToString();r++;}ws.RangeUsed().SetAutoFilter();ws.Columns().AdjustToContents();using var ms=new MemoryStream();wb.SaveAs(ms);return ms.ToArray();}
 public byte[] Evaluations(IEnumerable<(string Employee,string Evaluator,string Unit,string Position,decimal Score,decimal Max, string Status)> rows){using var wb=new XLWorkbook();var ws=wb.Worksheets.Add("گزارش ارزیابی");var h=new[]{"کارمند","ارزیاب","واحد","رده پستی","امتیاز","سقف","درصد","وضعیت"};for(int i=0;i<h.Length;i++)ws.Cell(1,i+1).Value=h[i];int r=2;foreach(var x in rows){ws.Cell(r,1).Value=x.Employee;ws.Cell(r,2).Value=x.Evaluator;ws.Cell(r,3).Value=x.Unit;ws.Cell(r,4).Value=x.Position;ws.Cell(r,5).Value=x.Score;ws.Cell(r,6).Value=x.Max;ws.Cell(r,7).Value=x.Max==0?0:Math.Round(x.Score/x.Max*100,2);ws.Cell(r,8).Value=x.Status;r++;}ws.RangeUsed().SetAutoFilter();ws.Columns().AdjustToContents();using var ms=new MemoryStream();wb.SaveAs(ms);return ms.ToArray();}
}